<script setup lang="ts">import{ref}from'vue';import{ElMessage}from'element-plus';import http from'../../api/http';const code=ref(''),data=ref<any>(null),loading=ref(false);async function load(){if(!code.value)return ElMessage.warning('请输入客户编码');loading.value=true;try{const r=await http.get(`/crm/customer-360/${code.value}`);data.value=r.data.data}catch(e:any){ElMessage.error(e.message||'客户查询失败')}finally{loading.value=false}}</script><template><section><div class="head"><div><span>客户全景视图</span><h1>客户360</h1><p>从客户主数据追溯商机、报价、合同、应收和客诉。</p></div></div><el-card shadow="never"><div class="search"><el-input v-model="code" placeholder="输入已发布客户编码" @keyup.enter="load"/><el-button type="primary" @click="load">查询</el-button></div><el-skeleton v-if="loading" :rows="6" animated/><template v-else-if="data"><el-descriptions title="客户档案" :column="3" border><el-descriptions-item v-for="(v,k) in data.customer" :key="k" :label="$zhKey(String(k))">{{$zh(v)}}</el-descriptions-item></el-descriptions><el-tabs><el-tab-pane v-for="(list,k) in data" v-show="String(k)!=='customer'" :key="k" :label="$zhKey(String(k))"><el-table :data="list" stripe><el-table-column v-for="field in Object.keys(list[0]||{}).slice(0,8)" :key="field" :label="$zhKey(field)"><template #default="{row}">{{$zh(row[field])}}</template></el-table-column></el-table></el-tab-pane></el-tabs></template><el-empty v-else description="输入客户编码查看完整业务链"/></el-card></section></template><style scoped>.head{margin-bottom:16px}.head span{font-size:11px;color:#3976d5}.head h1{margin:5px 0}.head p{color:#8391a4}.search{display:flex;gap:8px;margin-bottom:18px}.search .el-input{width:320px}</style>
